function compareModal(){const ids=state.favorites||[];const foods=ids.map(foodById).filter(Boolean).slice(0,3);if(foods.length<2)return toast('Добавьте в избранное хотя бы два корма');openModal(`<h2>Сравнить избранные корма</h2><div class="food-list">${foods.map(f=>`<div class="food-card"><div class="food-thumb">${foodImage(f)?`<img src="${esc(foodImage(f))}" alt="">`:'🥫'}</div><div><h3>${esc(f.brand)}<br>${esc(f.name)}</h3><p>${f.form==='wet'?'Влажный':'Сухой'} · ${f.kcalPer100g||'—'} ккал / 100 г</p><p>Белок ${f.proteinPer100g||'—'}% · жир ${f.fatPer100g||'—'}%</p></div></div>`).join('')}</div><button class="primary full" onclick="modal.close()">Готово</button>`)}
